window.COURSES={"pt":[{"title":"Primeiros cumprimentos","theme":"Saluda con naturalidad","goal":"Saludar y despedirte de alguien en Brasil.","words":[["Oi!","¡Hola!"],["Bom dia!","¡Buenos días!"],["Boa tarde!","¡Buenas tardes!"],["Boa noite!","¡Buenas noches!"],["Até logo!","¡Hasta luego!"]],"grammar":"En Brasil, «oi» es un saludo cotidiano. «Boa noite» sirve tanto para saludar por la noche como para despedirse.","dialogue":[["A","Oi! Bom dia!"],["B","Bom dia! Até logo!"]],"tip":"La «o» final sin acento suele sonar cercana a «u»: «logo» ≈ «lógu».","mission":["Escribe «Buenas tardes» en portugués.","Boa tarde!"]},{"title":"Quem é você?","theme":"Preséntate en 30 segundos","goal":"Decir tu nombre, origen e idioma.","words":[["Meu nome é...","Mi nombre es..."],["Eu sou colombiano.","Soy colombiano."],["Eu sou colombiana.","Soy colombiana."],["Prazer em conhecer você.","Mucho gusto en conocerte."],["Eu falo espanhol.","Hablo español."]],"grammar":"«Eu sou» significa «yo soy». «Meu nome é» se usa para presentarte. En Brasil se suele usar «você» como «tú/usted» según el contexto.","dialogue":[["A","Oi! Meu nome é Ana."],["B","Prazer em conhecer você!"]],"tip":"La «nh» suena como la «ñ» española: «conhecer» contiene un sonido nasal palatal.","mission":["Escribe «Hablo español» en portugués.","Eu falo espanhol."]},{"title":"Educação e gentileza","theme":"Palabras que abren puertas","goal":"Pedir ayuda y responder con cortesía.","words":[["Por favor.","Por favor."],["Obrigado.","Gracias (si habla un hombre)."],["Obrigada.","Gracias (si habla una mujer)."],["Com licença.","Con permiso."],["Desculpa.","Perdón / disculpa."]],"grammar":"En «obrigado/obrigada», la terminación suele concordar con quien da las gracias. «Com licença» sirve para pasar o llamar la atención.","dialogue":[["A","Com licença. Por favor!"],["B","Claro!"],["A","Obrigado!"]],"tip":"En el habla brasileña, «desculpa» suele sonar «des-KUL-pa»; marca la sílaba central.","mission":["Escribe «Con permiso» en portugués.","Com licença."]},{"title":"Números e idade","theme":"Cuenta y responde","goal":"Manejar números básicos y preguntar la edad.","words":[["Um, dois, três.","Uno, dos, tres."],["Quatro, cinco, seis.","Cuatro, cinco, seis."],["Sete, oito, nove.","Siete, ocho, nueve."],["Dez.","Diez."],["Quantos anos você tem?","¿Cuántos años tienes?"]],"grammar":"La edad se expresa con «ter»: «Eu tenho trinta anos» (tengo treinta años), no con «ser».","dialogue":[["A","Quantos anos você tem?"],["B","Eu tenho trinta anos."]],"tip":"«Três» tiene una «ê» cerrada y «anos» no lleva «h». Practica los números en voz alta.","mission":["Escribe «Diez» en portugués.","Dez."]},{"title":"Dias e horários","theme":"Ubícate en el tiempo","goal":"Hablar del día y de la hora.","words":[["Hoje.","Hoy."],["Amanhã.","Mañana."],["Ontem.","Ayer."],["Que horas são?","¿Qué hora es?"],["Às oito horas.","A las ocho."]],"grammar":"«Hoje», «ontem» y «amanhã» marcan el tiempo. Para decir «a las ocho», se usa «às oito horas».","dialogue":[["A","Que horas são?"],["B","São oito horas."],["A","Até amanhã!"]],"tip":"«Amanhã» termina con un sonido nasal «ã»; evita pronunciarlo como una «a» seca.","mission":["Escribe «¿Qué hora es?» en portugués.","Que horas são?"]},{"title":"Pessoas e família","theme":"Habla de tu gente","goal":"Describir relaciones y personas cercanas.","words":[["Minha família.","Mi familia."],["Meu amigo.","Mi amigo."],["Minha amiga.","Mi amiga."],["Meu irmão.","Mi hermano."],["Minha mãe.","Mi mamá / mi madre."]],"grammar":"«Meu» acompaña nombres masculinos y «minha» nombres femeninos: «meu amigo», «minha amiga».","dialogue":[["A","Quem é ela?"],["B","É minha amiga."],["A","E ele?"],["B","É meu irmão."]],"tip":"«Mãe» es nasal. «Irmão» termina en «ão», un diptongo nasal característico del portugués.","mission":["Escribe «Mi amiga» en portugués.","Minha amiga."]},{"title":"Checkpoint social","theme":"Semana 1 · Repaso","goal":"Construir tu primer intercambio social completo.","words":[["Tudo bem?","¿Todo bien?"],["Tudo ótimo!","¡Todo excelente!"],["E você?","¿Y tú?"],["De onde você é?","¿De dónde eres?"],["Sou da Colômbia.","Soy de Colombia."]],"grammar":"«Tudo bem?» funciona como «¿cómo estás?». Puedes responder «Tudo bem», «Tudo ótimo» o «mais ou menos».","dialogue":[["A","Oi! Tudo bem?"],["B","Tudo ótimo! E você?"],["A","Tudo bem! Sou da Colômbia."]],"tip":"«Você» suele pronunciarse «vo-SÊ». La «ê» final tiene una vocal cerrada.","mission":["Escribe «¿De dónde eres?» en portugués.","De onde você é?"]},{"title":"Na cafeteria","theme":"Pide tu café","goal":"Ordenar algo para beber con seguridad.","words":[["Um café, por favor.","Un café, por favor."],["Eu gostaria de...","Me gustaría..."],["Sem açúcar.","Sin azúcar."],["Com leite.","Con leche."],["A conta, por favor.","La cuenta, por favor."]],"grammar":"«Eu gostaria de» es una forma amable de pedir; puedes abreviarla como «Queria...» en muchos contextos.","dialogue":[["A","Eu gostaria de um café com leite."],["B","Com açúcar?"],["A","Não, sem açúcar."]],"tip":"«Açúcar» se escribe con «ç» y suena «a-SÚ-car». La «ç» siempre representa un sonido /s/.","mission":["Escribe «Sin azúcar» en portugués.","Sem açúcar."]},{"title":"No restaurante","theme":"Come sin perderte","goal":"Pedir comida y expresar lo que necesitas.","words":[["O cardápio, por favor.","El menú, por favor."],["Estou com fome.","Tengo hambre."],["Água sem gás.","Agua sin gas."],["Está delicioso!","¡Está delicioso!"],["Sou vegetariano.","Soy vegetariano."]],"grammar":"«Estou com fome» expresa hambre; también se dice «Estou com sede» (tengo sed). «Cardápio» es el menú en Brasil.","dialogue":[["A","O cardápio, por favor."],["B","Claro. Algo para beber?"],["A","Água sem gás."]],"tip":"«Água» se pronuncia con la primera sílaba fuerte: «Á-gua».","mission":["Escribe «Tengo hambre» en portugués.","Estou com fome."]},{"title":"Compras e preços","theme":"Compra como local","goal":"Preguntar precios y medios de pago.","words":[["Quanto custa?","¿Cuánto cuesta?"],["É muito caro.","Es muy caro."],["Tem desconto?","¿Hay descuento?"],["Posso pagar com cartão?","¿Puedo pagar con tarjeta?"],["Vou levar este.","Me llevo este."]],"grammar":"«Quanto custa?» para el precio de una cosa; «Quanto custam?» si preguntas por varias.","dialogue":[["A","Quanto custa?"],["B","Cinquenta reais."],["A","Tem desconto?"]],"tip":"En Brasil, la «r» inicial en «reais» suele sonar como una «j» suave española o una «h» aspirada, según el acento.","mission":["Escribe «¿Hay descuento?» en portugués.","Tem desconto?"]},{"title":"Onde fica?","theme":"Muévete por la ciudad","goal":"Pedir indicaciones y entender direcciones.","words":[["Onde fica o banheiro?","¿Dónde queda el baño?"],["À direita.","A la derecha."],["À esquerda.","A la izquierda."],["Siga em frente.","Siga derecho."],["É perto daqui?","¿Está cerca de aquí?"]],"grammar":"«Onde fica...?» pregunta por una ubicación. «À direita» y «à esquerda» indican dirección.","dialogue":[["A","Onde fica o banheiro?"],["B","Siga em frente e vire à direita."]],"tip":"«Esquerda» empieza con «es», parecido al español «izquierda», pero sin sonido de «i».","mission":["Escribe «A la izquierda» en portugués.","À esquerda."]},{"title":"Transporte","theme":"Taxi, bus y aeropuerto","goal":"Solicitar transporte y preguntar trayectos.","words":[["Preciso de um táxi.","Necesito un taxi."],["Onde fica a estação?","¿Dónde está la estación?"],["Quanto tempo demora?","¿Cuánto tiempo tarda?"],["Uma passagem, por favor.","Un pasaje, por favor."],["Pode parar aqui?","¿Puede parar aquí?"]],"grammar":"«Preciso de» equivale a «necesito». «Pode...?» es una petición útil y educada.","dialogue":[["A","Pode parar aqui?"],["B","Claro."],["A","Quanto custa a corrida?"]],"tip":"«Estação» acaba en «ão», nasal. «Passagem» termina en «gem» con sonido cercano a «yem» francés/portugués.","mission":["Escribe «¿Puede parar aquí?» en portugués.","Pode parar aqui?"]},{"title":"Hotel e viagem","theme":"Hospédate con confianza","goal":"Hacer check-in y resolver dudas de alojamiento.","words":[["Tenho uma reserva.","Tengo una reserva."],["Qual é o número do quarto?","¿Cuál es el número de habitación?"],["Tem Wi-Fi?","¿Hay Wi-Fi?"],["Preciso de ajuda.","Necesito ayuda."],["Onde é o café da manhã?","¿Dónde es el desayuno?"]],"grammar":"«Tenho» = «tengo». «Café da manhã» significa desayuno, no simplemente una taza de café.","dialogue":[["A","Boa noite, tenho uma reserva."],["B","Qual é o seu nome?"],["A","Meu nome é Carlos."]],"tip":"«Quarto» como habitación suele tener la «r» gutural o suave según la región; no es «cuarto» de cuarto de hora.","mission":["Escribe «Tengo una reserva» en portugués.","Tenho uma reserva."]},{"title":"Checkpoint de viagem","theme":"Semana 2 · Repaso","goal":"Combinar transporte, pedidos y orientación.","words":[["Estou perdido.","Estoy perdido."],["Você pode me ajudar?","¿Me puedes ayudar?"],["Não entendi.","No entendí."],["Pode repetir?","¿Puede repetir?"],["Fala mais devagar, por favor.","Habla más despacio, por favor."]],"grammar":"«Não» niega y «entendi» expresa «entendí». Aprende estas frases para continuar una conversación cuando no comprendas.","dialogue":[["A","Você pode me ajudar?"],["B","Claro!"],["A","Fala mais devagar, por favor."]],"tip":"«Não» suena nasal. No lo conviertas en «nao» con dos vocales completamente separadas.","mission":["Escribe «¿Puede repetir?» en portugués.","Pode repetir?"]},{"title":"Minha rotina","theme":"Cuenta tu día","goal":"Hablar de hábitos y horarios cotidianos.","words":[["Eu acordo cedo.","Me despierto temprano."],["Eu tomo café da manhã.","Desayuno."],["Eu trabalho de manhã.","Trabajo por la mañana."],["Eu estudo à noite.","Estudio por la noche."],["Eu vou dormir.","Voy a dormir."]],"grammar":"En presente, «eu trabalho», «eu estudo», «eu acordo» indican hábitos. «À noite» equivale a «por la noche».","dialogue":[["A","Você trabalha de manhã?"],["B","Sim, e estudo à noite."]],"tip":"«Trabalho» lleva «lh», parecido a «ll» palatal tradicional o «lli» suave.","mission":["Escribe «Estudio por la noche» en portugués.","Eu estudo à noite."]},{"title":"Verbos essenciais","theme":"Conjuga sin miedo","goal":"Usar ser, estar, tener y querer.","words":[["Eu sou...","Yo soy..."],["Eu estou...","Yo estoy..."],["Eu tenho...","Yo tengo..."],["Eu quero...","Yo quiero..."],["Eu posso...","Yo puedo..."]],"grammar":"Cinco verbos clave: ser → sou; estar → estou; ter → tenho; querer → quero; poder → posso (todos con «eu»).","dialogue":[["A","Você quer água?"],["B","Eu quero, obrigado!"],["A","Você está bem?"],["B","Sim, estou."]],"tip":"«Tenho» lleva «nh» con sonido parecido a «ñ». «Quero» se acentúa en «que».","mission":["Escribe «Yo puedo...» en portugués.","Eu posso..."]},{"title":"Gostos e preferências","theme":"Habla de lo que te gusta","goal":"Decir qué te gusta y qué prefieres.","words":[["Eu gosto de música.","Me gusta la música."],["Eu adoro viajar.","Me encanta viajar."],["Eu não gosto disso.","No me gusta eso."],["Eu prefiro café.","Prefiero café."],["Qual você prefere?","¿Cuál prefieres?"]],"grammar":"En portugués se dice «gostar de» (con la preposición «de»): «Eu gosto de café».","dialogue":[["A","Você gosta de música?"],["B","Adoro! E você?"],["A","Eu prefiro podcasts."]],"tip":"«Gosto» en muchos acentos de Brasil suena «GÓS-tu» y no tiene el mismo patrón que «gusto» español.","mission":["Escribe «Me encanta viajar» en portugués.","Eu adoro viajar."]},{"title":"Perguntas poderosas","theme":"Haz preguntas útiles","goal":"Formar preguntas para sostener una charla.","words":[["O que é isso?","¿Qué es eso?"],["Quem é você?","¿Quién eres?"],["Quando começa?","¿Cuándo empieza?"],["Por que não?","¿Por qué no?"],["Como funciona?","¿Cómo funciona?"]],"grammar":"«O que», «quem», «quando», «por que» y «como» permiten casi cualquier pregunta básica.","dialogue":[["A","Como funciona?"],["B","É simples."],["A","Quando começa?"],["B","Amanhã."]],"tip":"«Quem» es nasal. «Por que» se escribe separado cuando preguntas «¿por qué?».","mission":["Escribe «¿Cómo funciona?» en portugués.","Como funciona?"]},{"title":"Trabalho e reuniões","theme":"Tu portugués profesional","goal":"Presentarte y participar en reuniones laborales.","words":[["Tenho uma reunião.","Tengo una reunión."],["Trabalho com marketing.","Trabajo en marketing."],["Podemos conversar?","¿Podemos conversar?"],["Vamos começar.","Vamos a empezar."],["Você pode enviar o arquivo?","¿Puedes enviar el archivo?"]],"grammar":"«Trabalho com» se usa para hablar del área profesional; «podemos» expresa una propuesta o posibilidad conjunta.","dialogue":[["A","Você trabalha com o quê?"],["B","Trabalho com marketing."],["A","Podemos conversar amanhã?"]],"tip":"«Reunião» lleva sonido nasal al final. Pronúncialo por grupos: re-u-ni-ão.","mission":["Escribe «Podemos conversar?» en portugués.","Podemos conversar?"]},{"title":"Mensagens e convites","theme":"Coordina con otras personas","goal":"Enviar invitaciones y acordar horarios.","words":[["Você está livre hoje?","¿Estás libre hoy?"],["Vamos tomar um café?","¿Vamos a tomar un café?"],["Pode ser amanhã?","¿Puede ser mañana?"],["Me manda uma mensagem.","Mándame un mensaje."],["Combinado!","¡Quedamos así! / ¡De acuerdo!"]],"grammar":"«Vamos + infinitivo» hace propuestas. «Combinado!» confirma que el plan quedó acordado.","dialogue":[["A","Vamos tomar um café?"],["B","Pode ser amanhã?"],["A","Combinado!"]],"tip":"«Mensagem» termina en sonido nasal. En Brasil, «me manda» es muy común al hablar informalmente.","mission":["Escribe «¿Puede ser mañana?» en portugués.","Pode ser amanhã?"]},{"title":"Checkpoint de conversa","theme":"Semana 3 · Repaso","goal":"Mantener una conversación cotidiana de dos minutos.","words":[["O que você faz?","¿A qué te dedicas?"],["Eu moro em Cali.","Vivo en Cali."],["No meu tempo livre...","En mi tiempo libre..."],["Que interessante!","¡Qué interesante!"],["Me conta mais.","Cuéntame más."]],"grammar":"«Morar em» significa vivir en un lugar. «O que você faz?» puede preguntar por trabajo u ocupación.","dialogue":[["A","O que você faz?"],["B","Trabalho com marketing. E você?"],["A","Sou designer."],["B","Que interessante!"]],"tip":"«Interessante» se pronuncia con la fuerza en «san», y en Brasil la «te» final a menudo suena «chi».","mission":["Escribe «Vivo en Cali» en portugués.","Eu moro em Cali."]},{"title":"Falando do passado","theme":"Cuenta lo que hiciste","goal":"Hablar de acciones concretas del pasado.","words":[["Ontem eu trabalhei.","Ayer trabajé."],["Eu fui ao mercado.","Fui al mercado."],["Eu comi cedo.","Comí temprano."],["Eu gostei muito.","Me gustó mucho."],["Foi ótimo!","¡Fue excelente!"]],"grammar":"Pasado simple frecuente: trabalhar → trabalhei; comer → comi; ir/ser → fui. «Eu gostei» = me gustó.","dialogue":[["A","O que você fez ontem?"],["B","Eu fui ao mercado. Foi ótimo!"]],"tip":"«Fui» se pronuncia parecido al español «fui», pero cuida las vocales nasales en otras palabras.","mission":["Escribe «Ayer trabajé» en portugués.","Ontem eu trabalhei."]},{"title":"Planos e futuro","theme":"Habla de mañana","goal":"Expresar intenciones y planes cercanos.","words":[["Amanhã eu vou estudar.","Mañana voy a estudiar."],["Vou viajar em dezembro.","Viajaré en diciembre."],["Vamos nos encontrar.","Vamos a encontrarnos."],["Quero aprender mais.","Quiero aprender más."],["Tenho planos para o fim de semana.","Tengo planes para el fin de semana."]],"grammar":"«Ir» conjugado + infinitivo es una forma habitual de hablar del futuro: «Eu vou trabalhar».","dialogue":[["A","O que você vai fazer amanhã?"],["B","Vou estudar português."]],"tip":"«Dezembro» empieza con un sonido «de» que en muchos acentos brasileños se acerca a «dji».","mission":["Escribe «Quiero aprender más» en portugués.","Quero aprender mais."]},{"title":"Saúde e emergências","theme":"Pide ayuda con claridad","goal":"Expresar malestar y pedir auxilio.","words":[["Não me sinto bem.","No me siento bien."],["Preciso de um médico.","Necesito un médico."],["Onde fica o hospital?","¿Dónde queda el hospital?"],["Estou com dor de cabeça.","Me duele la cabeza."],["Chame uma ambulância!","¡Llame a una ambulancia!"]],"grammar":"«Estou com dor de...» señala dolor: «dor de cabeça» es dolor de cabeza. En emergencia, prioriza frases cortas y claras.","dialogue":[["A","Não me sinto bem."],["B","Quer ajuda?"],["A","Sim, preciso de um médico."]],"tip":"«Cabeça» lleva «ç» /s/. «Ambulância» lleva una «â» tónica y nasal antes de «n».","mission":["Escribe «Necesito un médico» en portugués.","Preciso de um médico."]},{"title":"Opiniões e conexões","theme":"Expresa tus ideas","goal":"Conectar frases y dar tu opinión.","words":[["Eu acho que sim.","Creo que sí."],["Na minha opinião...","En mi opinión..."],["Porque é importante.","Porque es importante."],["Mas depende.","Pero depende."],["Por isso...","Por eso..."]],"grammar":"«Eu acho que...» introduce opinión. «Mas» contrasta ideas y «por isso» expresa consecuencia.","dialogue":[["A","Você acha que vale a pena?"],["B","Eu acho que sim, mas depende."]],"tip":"«Acho» contiene «ch» con sonido «sh», no la «ch» fuerte española.","mission":["Escribe «En mi opinión...» en portugués.","Na minha opinião..."]},{"title":"Problemas e soluções","theme":"Explica lo que sucede","goal":"Reportar un problema y sugerir una solución.","words":[["Temos um problema.","Tenemos un problema."],["Não está funcionando.","No está funcionando."],["Podemos resolver isso.","Podemos resolver eso."],["Preciso de mais tempo.","Necesito más tiempo."],["Já está resolvido.","Ya está resuelto."]],"grammar":"«Já» = ya; «ainda» = todavía. «Está funcionando» describe una acción o estado en curso.","dialogue":[["A","Não está funcionando."],["B","Podemos resolver isso."],["A","Obrigado pela ajuda!"]],"tip":"«Resolver» tiene «s» sonora /z/ entre vocales; no es exactamente igual al español.","mission":["Escribe «Podemos resolver eso» en portugués.","Podemos resolver isso."]},{"title":"Marketing e negócios","theme":"Vocabulario de negocios","goal":"Hablar sobre campañas, clientes y resultados.","words":[["Nossa campanha teve bons resultados.","Nuestra campaña tuvo buenos resultados."],["Precisamos de mais clientes.","Necesitamos más clientes."],["Qual é o orçamento?","¿Cuál es el presupuesto?"],["Vamos analisar os dados.","Vamos a analizar los datos."],["A taxa de conversão aumentou.","La tasa de conversión aumentó."]],"grammar":"«Precisamos de» expresa necesidad colectiva. «Teve» es pasado de «ter». «Orçamento» significa presupuesto.","dialogue":[["A","Qual é o orçamento?"],["B","Vamos analisar os dados primeiro."]],"tip":"«Orçamento» usa «ç» con sonido /s/ y «ão» nasal. «Dados» = datos.","mission":["Escribe «¿Cuál es el presupuesto?» en portugués.","Qual é o orçamento?"]},{"title":"Negociação comercial","theme":"Conversa y llega a acuerdos","goal":"Negociar condiciones simples y fechas.","words":[["Podemos ajustar o preço?","¿Podemos ajustar el precio?"],["Qual é o prazo de entrega?","¿Cuál es el plazo de entrega?"],["Precisamos fechar o acordo.","Necesitamos cerrar el acuerdo."],["Pode enviar uma proposta?","¿Puede enviar una propuesta?"],["Vamos confirmar por e-mail.","Vamos a confirmar por correo."]],"grammar":"«Prazo» significa plazo y «fechar um acordo» cerrar un acuerdo. «Pode enviar...?» sirve para solicitar algo formalmente.","dialogue":[["A","Pode enviar uma proposta?"],["B","Claro. Até amanhã."],["A","Vamos confirmar por e-mail."]],"tip":"En Brasil «preço» lleva «ç» /s/ y «prazo» una «z» sonora /z/.","mission":["Escribe «¿Podemos ajustar el precio?» en portugués.","Podemos ajustar o preço?"]},{"title":"Desafio de conversação","theme":"Ensayo de conversación real","goal":"Unir preguntas, respuestas y conectores sin traducir palabra por palabra.","words":[["Pode falar um pouco sobre você?","¿Puedes hablar un poco de ti?"],["Eu comecei a aprender português.","Empecé a aprender portugués."],["Quero praticar todos os dias.","Quiero practicar todos los días."],["Ainda estou aprendendo.","Todavía estoy aprendiendo."],["Foi um prazer conversar!","¡Fue un placer conversar!"]],"grammar":"«Ainda» expresa «todavía»; «comecei a + infinitivo» indica inicio de una acción en el pasado.","dialogue":[["A","Pode falar um pouco sobre você?"],["B","Trabalho com marketing. Ainda estou aprendendo português."],["A","Muito bom!"]],"tip":"«Português» termina en «ês» y lleva el acento en la última sílaba.","mission":["Escribe «Todavía estoy aprendiendo» en portugués.","Ainda estou aprendendo."]},{"title":"Sua primeira apresentação","theme":"Día 30 · Meta final","goal":"Presentarte, hablar de tu trabajo y proponer una conversación.","words":[["Olá, meu nome é...","Hola, mi nombre es..."],["Sou da Colômbia e moro em Cali.","Soy de Colombia y vivo en Cali."],["Trabalho com marketing digital.","Trabajo con marketing digital."],["Estou aprendendo português.","Estoy aprendiendo portugués."],["Podemos conversar na próxima semana?","¿Podemos hablar la próxima semana?"]],"grammar":"Combina presente («sou», «moro», «trabalho»), progresivo («estou aprendendo») y futuro cercano para presentarte.","dialogue":[["A","Olá! Pode falar sobre você?"],["B","Sou da Colômbia, moro em Cali e trabalho com marketing digital."],["A","Que interessante!"],["B","Podemos conversar na próxima semana?"]],"tip":"Graba tu presentación de 45–60 segundos para comparar tu pronunciación con la voz en portugués.","mission":["Escribe «Estoy aprendiendo portugués» en portugués.","Estou aprendendo português."]}],"en":[{"title":"Hello there","theme":"Hello there","goal":"Aprender a comunicarte sobre hello there.","words":[["Hello!","¡Hola!"],["Good morning!","¡Buenos días!"],["Good afternoon!","¡Buenas tardes!"],["Good evening!","¡Buenas noches! (saludo)"],["See you later!","¡Hasta luego!"]],"grammar":"Use “good morning” before noon and “good evening” when arriving at night.","tip":"The initial h in hello is aspirated, unlike the silent h in Spanish.","mission":["Escribe en inglés: «¡Buenas noches! (saludo)»","Good evening!"]},{"title":"Nice to meet you","theme":"Nice to meet you","goal":"Aprender a comunicarte sobre nice to meet you.","words":[["My name is Alex.","Me llamo Alex."],["I'm from Colombia.","Soy de Colombia."],["Nice to meet you!","¡Mucho gusto!"],["I speak Spanish.","Hablo español."],["What is your name?","¿Cómo te llamas?"]],"grammar":"“I am” introduces who you are; “I'm” is its natural short form.","tip":"In “name”, the final e is silent and the a sounds /ei/.","mission":["Escribe en inglés: «Hablo español.»","I speak Spanish."]},{"title":"Please and thank you","theme":"Please and thank you","goal":"Aprender a comunicarte sobre please and thank you.","words":[["Please.","Por favor."],["Thank you very much.","Muchas gracias."],["You're welcome.","De nada."],["Excuse me.","Con permiso."],["I'm sorry.","Lo siento."]],"grammar":"“Please” softens requests. “You're welcome” responds to “thank you”.","tip":"“Thank” has the th sound: place your tongue lightly between your teeth.","mission":["Escribe en inglés: «Con permiso.»","Excuse me."]},{"title":"Numbers and age","theme":"Numbers and age","goal":"Aprender a comunicarte sobre numbers and age.","words":[["One, two, three.","Uno, dos, tres."],["Four, five, six.","Cuatro, cinco, seis."],["Seven, eight, nine.","Siete, ocho, nueve."],["Ten.","Diez."],["How old are you?","¿Cuántos años tienes?"]],"grammar":"With age, English uses “to be”: “I'm thirty”, not “I have thirty”.","tip":"“Three” begins with th; “thirteen” stresses the second syllable.","mission":["Escribe en inglés: «Diez.»","Ten."]},{"title":"Days and time","theme":"Days and time","goal":"Aprender a comunicarte sobre days and time.","words":[["Today.","Hoy."],["Tomorrow.","Mañana."],["Yesterday.","Ayer."],["What time is it?","¿Qué hora es?"],["At eight o'clock.","A las ocho en punto."]],"grammar":"“At” introduces an exact time: “at eight o'clock”.","tip":"In “Thursday”, th is a soft dental sound, not a Spanish t.","mission":["Escribe en inglés: «¿Qué hora es?»","What time is it?"]},{"title":"Friends and family","theme":"Friends and family","goal":"Aprender a comunicarte sobre friends and family.","words":[["My family.","Mi familia."],["My friend.","Mi amigo o amiga."],["My brother.","Mi hermano."],["My sister.","Mi hermana."],["My mother.","Mi madre."]],"grammar":"“My” is invariable: my mother, my brother and my friends.","tip":"“Brother” has an English r; don't roll it like the Spanish erre.","mission":["Escribe en inglés: «Mi hermana.»","My sister."]},{"title":"First conversation","theme":"First conversation","goal":"Aprender a comunicarte sobre first conversation.","words":[["How are you?","¿Cómo estás?"],["I'm great, thanks.","Muy bien, gracias."],["And you?","¿Y tú?"],["Where are you from?","¿De dónde eres?"],["I'm from Colombia.","Soy de Colombia."]],"grammar":"“Where are you from?” uses “are”; you can answer “I'm from…”.","tip":"“You” sounds /yu/ and “where” starts with a /w/ sound.","mission":["Escribe en inglés: «¿De dónde eres?»","Where are you from?"]},{"title":"At the coffee shop","theme":"At the coffee shop","goal":"Aprender a comunicarte sobre at the coffee shop.","words":[["A coffee, please.","Un café, por favor."],["I'd like a latte.","Me gustaría un café con leche."],["Without sugar.","Sin azúcar."],["With milk.","Con leche."],["The bill, please.","La cuenta, por favor."]],"grammar":"“I'd like” is a polite way to order. “With” and “without” change your order.","tip":"“Coffee” is stressed on the first syllable: COF-fee.","mission":["Escribe en inglés: «Con leche.»","With milk."]},{"title":"At a restaurant","theme":"At a restaurant","goal":"Aprender a comunicarte sobre at a restaurant.","words":[["The menu, please.","El menú, por favor."],["I'm hungry.","Tengo hambre."],["Still water.","Agua sin gas."],["It's delicious!","¡Está delicioso!"],["Can I have a table for two?","¿Me puede dar una mesa para dos?"]],"grammar":"“Can I have…?” is a friendly request. “I'm hungry” uses “to be”.","tip":"“Menu” in English has stress on the first syllable: MEN-yoo.","mission":["Escribe en inglés: «¡Está delicioso!»","It's delicious!"]},{"title":"Shopping and prices","theme":"Shopping and prices","goal":"Aprender a comunicarte sobre shopping and prices.","words":[["How much is it?","¿Cuánto cuesta?"],["That's too expensive.","Eso es demasiado caro."],["Do you have a discount?","¿Tiene descuento?"],["Can I pay by card?","¿Puedo pagar con tarjeta?"],["I'll take this one.","Me llevo este."]],"grammar":"“How much” asks price. For plural goods, ask “How much are these?”.","tip":"“Cheap” and “ship” sound different; extend the ee in cheap.","mission":["Escribe en inglés: «¿Puedo pagar con tarjeta?»","Can I pay by card?"]},{"title":"Asking for directions","theme":"Asking for directions","goal":"Aprender a comunicarte sobre asking for directions.","words":[["Where is the bathroom?","¿Dónde queda el baño?"],["Turn right.","Gira a la derecha."],["Turn left.","Gira a la izquierda."],["Go straight ahead.","Sigue derecho."],["Is it near here?","¿Está cerca de aquí?"]],"grammar":"“Where is…?” and “How do I get to…?” help you navigate.","tip":"The “r” in “right” is not rolled. Practice right versus light.","mission":["Escribe en inglés: «Sigue derecho.»","Go straight ahead."]},{"title":"Getting around","theme":"Getting around","goal":"Aprender a comunicarte sobre getting around.","words":[["I need a taxi.","Necesito un taxi."],["Where is the station?","¿Dónde está la estación?"],["How long does it take?","¿Cuánto tiempo tarda?"],["One ticket, please.","Un tiquete, por favor."],["Can you stop here?","¿Puede parar aquí?"]],"grammar":"“How long does it take?” asks duration, not cost.","tip":"The t in “station” becomes /sh/: STAY-shən.","mission":["Escribe en inglés: «Un tiquete, por favor.»","One ticket, please."]},{"title":"At the hotel","theme":"At the hotel","goal":"Aprender a comunicarte sobre at the hotel.","words":[["I have a reservation.","Tengo una reserva."],["What's my room number?","¿Cuál es mi número de habitación?"],["Is there Wi-Fi?","¿Hay Wi-Fi?"],["I need help.","Necesito ayuda."],["Where is breakfast served?","¿Dónde sirven el desayuno?"]],"grammar":"“I have a reservation” works at hotels and restaurants.","tip":"“Room” has a long u sound; avoid pronouncing it like Spanish rum.","mission":["Escribe en inglés: «Necesito ayuda.»","I need help."]},{"title":"Travel checkpoint","theme":"Travel checkpoint","goal":"Aprender a comunicarte sobre travel checkpoint.","words":[["I'm lost.","Estoy perdido."],["Can you help me?","¿Me puedes ayudar?"],["I don't understand.","No entiendo."],["Could you repeat that?","¿Podrías repetir eso?"],["Please speak more slowly.","Habla más despacio, por favor."]],"grammar":"When lost, politely ask the speaker to slow down or repeat.","tip":"“Could” sounds close to /kud/; the l is silent.","mission":["Escribe en inglés: «¿Podrías repetir eso?»","Could you repeat that?"]},{"title":"My daily routine","theme":"My daily routine","goal":"Aprender a comunicarte sobre my daily routine.","words":[["I wake up early.","Me despierto temprano."],["I have breakfast.","Desayuno."],["I work in the morning.","Trabajo por la mañana."],["I study at night.","Estudio por la noche."],["I go to bed at ten.","Me acuesto a las diez."]],"grammar":"The simple present describes routines: I wake up, I work, I study.","tip":"“Work” rhymes with “first” in many accents.","mission":["Escribe en inglés: «Estudio por la noche.»","I study at night."]},{"title":"Essential verbs","theme":"Essential verbs","goal":"Aprender a comunicarte sobre essential verbs.","words":[["I am ready.","Estoy listo."],["I have an idea.","Tengo una idea."],["I want to learn.","Quiero aprender."],["I need more time.","Necesito más tiempo."],["I can do it.","Puedo hacerlo."]],"grammar":"“I am”, “I have”, “I want” and “I need” cover many conversations.","tip":"“Want” has a clear /w/ start, unlike Spanish gu.","mission":["Escribe en inglés: «Necesito más tiempo.»","I need more time."]},{"title":"Asking questions","theme":"Asking questions","goal":"Aprender a comunicarte sobre asking questions.","words":[["Do you speak English?","¿Hablas inglés?"],["What do you do?","¿A qué te dedicas?"],["Where do you live?","¿Dónde vives?"],["Why is that important?","¿Por qué es importante?"],["Can you explain it?","¿Puedes explicarlo?"]],"grammar":"“Do you…?” introduces many simple-present questions.","tip":"“Do” sounds /du/; “does” sounds /daz/.","mission":["Escribe en inglés: «¿Por qué es importante?»","Why is that important?"]},{"title":"Weather and seasons","theme":"Weather and seasons","goal":"Aprender a comunicarte sobre weather and seasons.","words":[["It's sunny today.","Hoy está soleado."],["It's raining.","Está lloviendo."],["It's very hot.","Hace mucho calor."],["It's cold outside.","Hace frío afuera."],["What's the weather like?","¿Qué tiempo hace?"]],"grammar":"Weather often uses “it”: It's hot, it's sunny, it's raining.","tip":"“Weather” starts with /w/ and has the same th as “this”.","mission":["Escribe en inglés: «Hace frío afuera.»","It's cold outside."]},{"title":"Feelings and opinions","theme":"Feelings and opinions","goal":"Aprender a comunicarte sobre feelings and opinions.","words":[["I'm happy.","Estoy feliz."],["I'm tired.","Estoy cansado."],["I'm excited.","Estoy emocionado."],["I think it's a good idea.","Creo que es una buena idea."],["I agree with you.","Estoy de acuerdo contigo."]],"grammar":"“I feel” describes emotions. “I think” introduces an opinion.","tip":"“Think” starts with the voiceless th sound.","mission":["Escribe en inglés: «Creo que es una buena idea.»","I think it's a good idea."]},{"title":"Talking about yesterday","theme":"Talking about yesterday","goal":"Aprender a comunicarte sobre talking about yesterday.","words":[["I worked yesterday.","Trabajé ayer."],["I visited a friend.","Visité a un amigo."],["I went to the office.","Fui a la oficina."],["I had a meeting.","Tuve una reunión."],["It was great.","Fue genial."]],"grammar":"Regular past verbs often end in -ed, with different pronunciations.","tip":"“Worked” ends with /t/, not an extra syllable /ed/.","mission":["Escribe en inglés: «Tuve una reunión.»","I had a meeting."]},{"title":"Conversation checkpoint","theme":"Conversation checkpoint","goal":"Aprender a comunicarte sobre conversation checkpoint.","words":[["How was your day?","¿Cómo estuvo tu día?"],["It was very productive.","Fue muy productivo."],["What did you do?","¿Qué hiciste?"],["I learned something new.","Aprendí algo nuevo."],["That sounds interesting.","Eso suena interesante."]],"grammar":"Alternate present and past to describe what happened and how it went.","tip":"Join words naturally: “How was it?” flows together.","mission":["Escribe en inglés: «Aprendí algo nuevo.»","I learned something new."]},{"title":"Making plans","theme":"Making plans","goal":"Aprender a comunicarte sobre making plans.","words":[["I'm going to travel.","Voy a viajar."],["We will meet tomorrow.","Nos reuniremos mañana."],["What are your plans?","¿Cuáles son tus planes?"],["I'm available on Friday.","Estoy disponible el viernes."],["Let's schedule a call.","Programemos una llamada."]],"grammar":"“Going to” often describes plans; “will” can express quick decisions.","tip":"In fast speech, “going to” may sound like “gonna”; prefer full form initially.","mission":["Escribe en inglés: «Estoy disponible el viernes.»","I'm available on Friday."]},{"title":"Calls and messages","theme":"Calls and messages","goal":"Aprender a comunicarte sobre calls and messages.","words":[["Can you hear me?","¿Puedes oírme?"],["The connection is bad.","La conexión es mala."],["Please send me a message.","Envíame un mensaje, por favor."],["I'll call you later.","Te llamaré más tarde."],["Could you send the file?","¿Podrías enviar el archivo?"]],"grammar":"“Could you…” is courteous in professional messages.","tip":"“Message” stresses MES, not -sage.","mission":["Escribe en inglés: «Te llamaré más tarde.»","I'll call you later."]},{"title":"At work","theme":"At work","goal":"Aprender a comunicarte sobre at work.","words":[["I work in marketing.","Trabajo en marketing."],["I'm the team leader.","Soy el líder del equipo."],["We have a new project.","Tenemos un proyecto nuevo."],["I work with clients.","Trabajo con clientes."],["We need a proposal.","Necesitamos una propuesta."]],"grammar":"“I'm responsible for…” explains your role; “I work in…” your area.","tip":"“Project” stresses PRO on the noun.","mission":["Escribe en inglés: «Trabajo con clientes.»","I work with clients."]},{"title":"Meetings and presentations","theme":"Meetings and presentations","goal":"Aprender a comunicarte sobre meetings and presentations.","words":[["Let's start the meeting.","Empecemos la reunión."],["What's on the agenda?","¿Qué hay en la agenda?"],["I have a question.","Tengo una pregunta."],["Let me share my screen.","Déjame compartir mi pantalla."],["What are the next steps?","¿Cuáles son los siguientes pasos?"]],"grammar":"“Let's” is a collaborative way to propose action.","tip":"“Agenda” in English stresses the second syllable: a-GEN-da.","mission":["Escribe en inglés: «Déjame compartir mi pantalla.»","Let me share my screen."]},{"title":"Digital marketing","theme":"Digital marketing","goal":"Aprender a comunicarte sobre digital marketing.","words":[["We need more leads.","Necesitamos más clientes potenciales."],["Our target audience is growing.","Nuestro público objetivo está creciendo."],["Let's test two ads.","Probemos dos anuncios."],["What's the conversion rate?","¿Cuál es la tasa de conversión?"],["This campaign is working.","Esta campaña está funcionando."]],"grammar":"English campaigns use “target audience”, “leads” and “conversion rate”.","tip":"“Audience” begins with AW, not like the Spanish “audiencia”.","mission":["Escribe en inglés: «¿Cuál es la tasa de conversión?»","What's the conversion rate?"]},{"title":"E-commerce metrics","theme":"E-commerce metrics","goal":"Aprender a comunicarte sobre e-commerce metrics.","words":[["Sales increased this month.","Las ventas aumentaron este mes."],["Our average order value is higher.","Nuestro ticket promedio es mayor."],["We need to reduce costs.","Necesitamos reducir costos."],["What's our return on ad spend?","¿Cuál es nuestro retorno sobre inversión publicitaria?"],["Let's review the dashboard.","Revisemos el tablero de indicadores."]],"grammar":"“Revenue” is sales income; “profit” subtracts costs. “ROAS” is ad revenue divided by ad spend.","tip":"“Revenue” often sounds REV-ə-new.","mission":["Escribe en inglés: «¿Cuál es nuestro retorno sobre inversión publicitaria?»","What's our return on ad spend?"]},{"title":"Negotiation","theme":"Negotiation","goal":"Aprender a comunicarte sobre negotiation.","words":[["What's your budget?","¿Cuál es tu presupuesto?"],["Can we discuss the price?","¿Podemos hablar del precio?"],["We can offer a discount.","Podemos ofrecer un descuento."],["Let's agree on the deadline.","Acordemos la fecha límite."],["That works for me.","Eso me funciona."]],"grammar":"Polite negotiation uses “Could we…?”, “Would you…?” and concrete terms.","tip":"“Budget” is BUD-jit; the d and g blend into /dʒ/.","mission":["Escribe en inglés: «Acordemos la fecha límite.»","Let's agree on the deadline."]},{"title":"Your professional story","theme":"Your professional story","goal":"Aprender a comunicarte sobre your professional story.","words":[["I lead a marketing agency.","Dirijo una agencia de marketing."],["We help brands grow.","Ayudamos a las marcas a crecer."],["My main goal is growth.","Mi objetivo principal es crecer."],["I have experience in advertising.","Tengo experiencia en publicidad."],["I'd like to work together.","Me gustaría trabajar juntos."]],"grammar":"“I have worked…” is useful for experience continuing to the present.","tip":"“Experience” stresses SPEER: ex-PEER-ee-əns.","mission":["Escribe en inglés: «Tengo experiencia en publicidad.»","I have experience in advertising."]},{"title":"Final challenge","theme":"Final challenge","goal":"Aprender a comunicarte sobre final challenge.","words":[["Hello, it's a pleasure to meet you.","Hola, es un placer conocerte."],["Let me introduce our business.","Déjame presentar nuestro negocio."],["We help companies get results.","Ayudamos a las empresas a obtener resultados."],["What challenge are you facing?","¿Qué desafío estás enfrentando?"],["Let's book a meeting next week.","Agendemos una reunión la próxima semana."]],"grammar":"Combine greetings, clear value, a question and a next step.","tip":"Pause between ideas; clear rhythm matters more than speed.","mission":["Escribe en inglés: «¿Qué desafío estás enfrentando?»","What challenge are you facing?"]}],"fr":[{"title":"Bonjour et salutations","theme":"Bonjour et salutations","goal":"Aprender a comunicarte sobre bonjour et salutations.","words":[["Bonjour !","¡Buenos días! / ¡Hola!"],["Bonsoir !","¡Buenas noches! (saludo)"],["Salut !","¡Hola! (informal)"],["Au revoir !","¡Adiós!"],["À bientôt !","¡Hasta pronto!"]],"grammar":"“Bonjour” sirve de día; “bonsoir” al saludar de noche y “bonne nuit” al despedirse para dormir.","tip":"En «bonjour» la j suena /ʒ/, como una y muy suave con fricción.","mission":["Escribe en francés: «¡Adiós!»","Au revoir !"]},{"title":"Se présenter","theme":"Se présenter","goal":"Aprender a comunicarte sobre se présenter.","words":[["Je m'appelle Alex.","Me llamo Alex."],["Je suis colombien.","Soy colombiano."],["Je suis colombienne.","Soy colombiana."],["Enchanté !","¡Mucho gusto! (hablante masculino)"],["Je parle espagnol.","Hablo español."]],"grammar":"Para decir tu nombre se usa «Je m'appelle…». «Je suis» sirve para nacionalidad.","tip":"La u de «tu» no suena como la u española: redondea los labios como para u diciendo i.","mission":["Escribe en francés: «¡Mucho gusto! (hablante masculino)»","Enchanté !"]},{"title":"La politesse","theme":"La politesse","goal":"Aprender a comunicarte sobre la politesse.","words":[["S'il vous plaît.","Por favor. (formal)"],["Merci beaucoup.","Muchas gracias."],["De rien.","De nada."],["Excusez-moi.","Discúlpeme."],["Je suis désolé.","Lo siento. (hablante masculino)"]],"grammar":"«S'il vous plaît» es formal; «s'il te plaît» es informal.","tip":"La r francesa suele ser uvular; practica suavemente sin exagerar.","mission":["Escribe en francés: «Discúlpeme.»","Excusez-moi."]},{"title":"Les nombres et l'âge","theme":"Les nombres et l'âge","goal":"Aprender a comunicarte sobre les nombres et l'âge.","words":[["Un, deux, trois.","Uno, dos, tres."],["Quatre, cinq, six.","Cuatro, cinco, seis."],["Sept, huit, neuf.","Siete, ocho, nueve."],["Dix.","Diez."],["Quel âge avez-vous ?","¿Cuántos años tiene?"]],"grammar":"En francés, la edad se expresa con «avoir»: «J'ai trente ans».","tip":"Los sonidos nasales de «un» y «cinq» no se pronuncian como en español.","mission":["Escribe en francés: «Diez.»","Dix."]},{"title":"Les jours et l'heure","theme":"Les jours et l'heure","goal":"Aprender a comunicarte sobre les jours et l'heure.","words":[["Aujourd'hui.","Hoy."],["Demain.","Mañana."],["Hier.","Ayer."],["Quelle heure est-il ?","¿Qué hora es?"],["À huit heures.","A las ocho."]],"grammar":"«À huit heures» significa «a las ocho»; «demain» es mañana.","tip":"En «heure», la h es muda.","mission":["Escribe en francés: «¿Qué hora es?»","Quelle heure est-il ?"]},{"title":"La famille et les amis","theme":"La famille et les amis","goal":"Aprender a comunicarte sobre la famille et les amis.","words":[["Ma famille.","Mi familia."],["Mon ami.","Mi amigo."],["Mon amie.","Mi amiga."],["Mon frère.","Mi hermano."],["Ma mère.","Mi madre."]],"grammar":"«Mon» y «ma» son posesivos; antes de vocal se usa «mon» incluso con algunos nombres femeninos.","tip":"«Frère» requiere la r francesa y una e abierta.","mission":["Escribe en francés: «Mi hermano.»","Mon frère."]},{"title":"Première conversation","theme":"Première conversation","goal":"Aprender a comunicarte sobre première conversation.","words":[["Ça va ?","¿Cómo estás?"],["Très bien, merci.","Muy bien, gracias."],["Et vous ?","¿Y usted?"],["Vous venez d'où ?","¿De dónde viene usted?"],["Je viens de Colombie.","Vengo de Colombia."]],"grammar":"«Comment allez-vous ?» es más formal que «Ça va ?».","tip":"«Vous» suena «vu» con u francesa, no como la u española.","mission":["Escribe en francés: «¿De dónde viene usted?»","Vous venez d'où ?"]},{"title":"Au café","theme":"Au café","goal":"Aprender a comunicarte sobre au café.","words":[["Un café, s'il vous plaît.","Un café, por favor."],["Je voudrais un café au lait.","Quisiera un café con leche."],["Sans sucre.","Sin azúcar."],["Avec du lait.","Con leche."],["L'addition, s'il vous plaît.","La cuenta, por favor."]],"grammar":"«Je voudrais…» es una forma cortés de pedir. «Sans» significa sin.","tip":"La «é» de café es cerrada; el acento marca el sonido.","mission":["Escribe en francés: «Con leche.»","Avec du lait."]},{"title":"Au restaurant","theme":"Au restaurant","goal":"Aprender a comunicarte sobre au restaurant.","words":[["La carte, s'il vous plaît.","El menú, por favor."],["J'ai faim.","Tengo hambre."],["De l'eau plate.","Agua sin gas."],["C'est délicieux !","¡Está delicioso!"],["Une table pour deux, s'il vous plaît.","Una mesa para dos, por favor."]],"grammar":"«J'ai faim» significa literalmente «tengo hambre».","tip":"«Eau» se pronuncia /o/, con una sola vocal.","mission":["Escribe en francés: «¡Está delicioso!»","C'est délicieux !"]},{"title":"Faire des achats","theme":"Faire des achats","goal":"Aprender a comunicarte sobre faire des achats.","words":[["Combien ça coûte ?","¿Cuánto cuesta?"],["C'est trop cher.","Está muy caro."],["Vous faites une réduction ?","¿Hace un descuento?"],["Je peux payer par carte ?","¿Puedo pagar con tarjeta?"],["Je prends celui-ci.","Me llevo este."]],"grammar":"«Combien ça coûte ?» pregunta el precio; «cher» indica caro.","tip":"En «prix», la x final es muda.","mission":["Escribe en francés: «¿Puedo pagar con tarjeta?»","Je peux payer par carte ?"]},{"title":"Demander son chemin","theme":"Demander son chemin","goal":"Aprender a comunicarte sobre demander son chemin.","words":[["Où sont les toilettes ?","¿Dónde están los baños?"],["Tournez à droite.","Gire a la derecha."],["Tournez à gauche.","Gire a la izquierda."],["Allez tout droit.","Siga derecho."],["C'est près d'ici ?","¿Está cerca de aquí?"]],"grammar":"«Où se trouve… ?» es una forma habitual de preguntar ubicación.","tip":"«Droite» suena aproximadamente «druat»; no pronuncies todas sus letras.","mission":["Escribe en francés: «Siga derecho.»","Allez tout droit."]},{"title":"Les transports","theme":"Les transports","goal":"Aprender a comunicarte sobre les transports.","words":[["J'ai besoin d'un taxi.","Necesito un taxi."],["Où est la gare ?","¿Dónde está la estación de tren?"],["Ça prend combien de temps ?","¿Cuánto tiempo tarda?"],["Un billet, s'il vous plaît.","Un tiquete, por favor."],["Vous pouvez vous arrêter ici ?","¿Puede parar aquí?"]],"grammar":"«Il faut combien de temps ?» pregunta duración.","tip":"En «station» la t se pronuncia /s/: sta-SION.","mission":["Escribe en francés: «Un tiquete, por favor.»","Un billet, s'il vous plaît."]},{"title":"À l'hôtel","theme":"À l'hôtel","goal":"Aprender a comunicarte sobre à l'hôtel.","words":[["J'ai une réservation.","Tengo una reserva."],["Quel est le numéro de ma chambre ?","¿Cuál es el número de mi habitación?"],["Il y a du Wi-Fi ?","¿Hay Wi-Fi?"],["J'ai besoin d'aide.","Necesito ayuda."],["Où est servi le petit-déjeuner ?","¿Dónde sirven el desayuno?"]],"grammar":"«J'ai une réservation» sirve para anunciar tu reserva al llegar.","tip":"«Chambre» suena más cercano a «shambr»; la combinación ch es /ʃ/.","mission":["Escribe en francés: «Necesito ayuda.»","J'ai besoin d'aide."]},{"title":"Révision de voyage","theme":"Révision de voyage","goal":"Aprender a comunicarte sobre révision de voyage.","words":[["Je suis perdu.","Estoy perdido."],["Vous pouvez m'aider ?","¿Me puede ayudar?"],["Je ne comprends pas.","No entiendo."],["Vous pouvez répéter ?","¿Puede repetir?"],["Parlez plus lentement, s'il vous plaît.","Hable más despacio, por favor."]],"grammar":"Para pedir ayuda, «Pouvez-vous… ?» es cortés.","tip":"En «lentement» las letras finales no se pronuncian completas.","mission":["Escribe en francés: «¿Puede repetir?»","Vous pouvez répéter ?"]},{"title":"Ma routine","theme":"Ma routine","goal":"Aprender a comunicarte sobre ma routine.","words":[["Je me réveille tôt.","Me despierto temprano."],["Je prends mon petit-déjeuner.","Desayuno."],["Je travaille le matin.","Trabajo por la mañana."],["J'étudie le soir.","Estudio por la noche."],["Je me couche à dix heures.","Me acuesto a las diez."]],"grammar":"El presente «je travaille» describe hábitos; «le matin» significa por la mañana.","tip":"En «travaille», «ill» suena /j/, como una y ligera.","mission":["Escribe en francés: «Estudio por la noche.»","J'étudie le soir."]},{"title":"Verbes indispensables","theme":"Verbes indispensables","goal":"Aprender a comunicarte sobre verbes indispensables.","words":[["Je suis prêt.","Estoy listo. (hablante masculino)"],["J'ai une idée.","Tengo una idea."],["Je veux apprendre.","Quiero aprender."],["J'ai besoin de temps.","Necesito tiempo."],["Je peux le faire.","Puedo hacerlo."]],"grammar":"«Je suis», «j'ai», «je veux», «je peux» son formas útiles de los verbos básicos.","tip":"En «veux» se pronuncia una vocal redondeada /ø/; la x es muda.","mission":["Escribe en francés: «Necesito tiempo.»","J'ai besoin de temps."]},{"title":"Poser des questions","theme":"Poser des questions","goal":"Aprender a comunicarte sobre poser des questions.","words":[["Vous parlez français ?","¿Habla francés?"],["Qu'est-ce que vous faites ?","¿A qué se dedica?"],["Où habitez-vous ?","¿Dónde vive?"],["Pourquoi est-ce important ?","¿Por qué es importante?"],["Vous pouvez expliquer ?","¿Puede explicar?"]],"grammar":"«Est-ce que» introduce preguntas sin invertir sujeto y verbo.","tip":"«Qu'est-ce que» suele sonar como «kes-ke» al hablar.","mission":["Escribe en francés: «¿Por qué es importante?»","Pourquoi est-ce important ?"]},{"title":"Le temps et les saisons","theme":"Le temps et les saisons","goal":"Aprender a comunicarte sobre le temps et les saisons.","words":[["Il fait beau aujourd'hui.","Hoy hace buen tiempo."],["Il pleut.","Está lloviendo."],["Il fait très chaud.","Hace mucho calor."],["Il fait froid dehors.","Hace frío afuera."],["Quel temps fait-il ?","¿Qué tiempo hace?"]],"grammar":"«Il fait» se usa para calor o frío, «il pleut» para lluvia.","tip":"La vocal «eu» en «pleut» requiere redondear los labios.","mission":["Escribe en francés: «Hace frío afuera.»","Il fait froid dehors."]},{"title":"Émotions et opinions","theme":"Émotions et opinions","goal":"Aprender a comunicarte sobre émotions et opinions.","words":[["Je suis heureux.","Estoy feliz. (hablante masculino)"],["Je suis fatigué.","Estoy cansado. (hablante masculino)"],["Je suis enthousiaste.","Estoy entusiasmado."],["Je pense que c'est une bonne idée.","Creo que es una buena idea."],["Je suis d'accord avec vous.","Estoy de acuerdo con usted."]],"grammar":"«Je pense que…» introduce una opinión. Para estados, usa «Je suis…».","tip":"«Heureux» no se lee literalmente: la h es muda y la x también.","mission":["Escribe en francés: «Creo que es una buena idea.»","Je pense que c'est une bonne idée."]},{"title":"Parler du passé","theme":"Parler du passé","goal":"Aprender a comunicarte sobre parler du passé.","words":[["J'ai travaillé hier.","Trabajé ayer."],["J'ai rendu visite à un ami.","Visité a un amigo."],["Je suis allé au bureau.","Fui a la oficina. (hablante masculino)"],["J'ai eu une réunion.","Tuve una reunión."],["C'était super.","Fue genial."]],"grammar":"El «passé composé» combina auxiliar y participio: «j'ai travaillé».","tip":"El participio «travaillé» termina en sonido /e/; no agregues d.","mission":["Escribe en francés: «Tuve una reunión.»","J'ai eu une réunion."]},{"title":"Bilan des conversations","theme":"Bilan des conversations","goal":"Aprender a comunicarte sobre bilan des conversations.","words":[["Comment s'est passée ta journée ?","¿Cómo estuvo tu día?"],["C'était très productif.","Fue muy productivo."],["Qu'est-ce que tu as fait ?","¿Qué hiciste?"],["J'ai appris quelque chose de nouveau.","Aprendí algo nuevo."],["C'est intéressant !","¡Eso es interesante!"]],"grammar":"«Qu'est-ce que tu as fait ?» pregunta qué hiciste, en trato informal.","tip":"En francés hablado se unen muchas palabras: «vous avez» /vu-zavé/.","mission":["Escribe en francés: «Aprendí algo nuevo.»","J'ai appris quelque chose de nouveau."]},{"title":"Faire des projets","theme":"Faire des projets","goal":"Aprender a comunicarte sobre faire des projets.","words":[["Je vais voyager.","Voy a viajar."],["Nous allons nous voir demain.","Vamos a vernos mañana."],["Quels sont vos projets ?","¿Cuáles son sus planes?"],["Je suis disponible vendredi.","Estoy disponible el viernes."],["Fixons un appel.","Programemos una llamada."]],"grammar":"«Je vais + infinitivo» expresa futuro cercano.","tip":"«Demain» contiene una vocal nasal; no cierres en n dura.","mission":["Escribe en francés: «Estoy disponible el viernes.»","Je suis disponible vendredi."]},{"title":"Appels et messages","theme":"Appels et messages","goal":"Aprender a comunicarte sobre appels et messages.","words":[["Vous m'entendez ?","¿Me escucha?"],["La connexion est mauvaise.","La conexión es mala."],["Envoyez-moi un message, s'il vous plaît.","Envíeme un mensaje, por favor."],["Je vous rappellerai plus tard.","Le devolveré la llamada más tarde."],["Pourriez-vous envoyer le fichier ?","¿Podría enviar el archivo?"]],"grammar":"«Pourriez-vous… ?» funciona muy bien para solicitudes formales.","tip":"En «appel» la última consonante l se pronuncia claramente.","mission":["Escribe en francés: «Le devolveré la llamada más tarde.»","Je vous rappellerai plus tard."]},{"title":"Au travail","theme":"Au travail","goal":"Aprender a comunicarte sobre au travail.","words":[["Je travaille dans le marketing.","Trabajo en marketing."],["Je dirige une équipe.","Dirijo un equipo."],["Nous avons un nouveau projet.","Tenemos un nuevo proyecto."],["Je travaille avec des clients.","Trabajo con clientes."],["Nous avons besoin d'une proposition.","Necesitamos una propuesta."]],"grammar":"«Je travaille dans…» indica sector y «avec…» indica colaboración.","tip":"«Travail» termina con sonido /vaj/, no /val/.","mission":["Escribe en francés: «Trabajo con clientes.»","Je travaille avec des clients."]},{"title":"Réunions et présentations","theme":"Réunions et présentations","goal":"Aprender a comunicarte sobre réunions et présentations.","words":[["Commençons la réunion.","Empecemos la reunión."],["Quel est l'ordre du jour ?","¿Cuál es la agenda?"],["J'ai une question.","Tengo una pregunta."],["Je vais partager mon écran.","Voy a compartir mi pantalla."],["Quelles sont les prochaines étapes ?","¿Cuáles son los siguientes pasos?"]],"grammar":"«Commençons» es invitación colectiva a empezar.","tip":"«Réunion» tiene la u francesa y termina en sonido nasal /ɔ̃/.","mission":["Escribe en francés: «Voy a compartir mi pantalla.»","Je vais partager mon écran."]},{"title":"Marketing numérique","theme":"Marketing numérique","goal":"Aprender a comunicarte sobre marketing numérique.","words":[["Nous avons besoin de plus de prospects.","Necesitamos más clientes potenciales."],["Notre public cible grandit.","Nuestro público objetivo está creciendo."],["Testons deux annonces.","Probemos dos anuncios."],["Quel est le taux de conversion ?","¿Cuál es la tasa de conversión?"],["Cette campagne fonctionne bien.","Esta campaña está funcionando bien."]],"grammar":"«Public cible» es público objetivo; «taux de conversion» es tasa de conversión.","tip":"«Cible» se pronuncia «sibl»: la c ante i es /s/.","mission":["Escribe en francés: «¿Cuál es la tasa de conversión?»","Quel est le taux de conversion ?"]},{"title":"Indicateurs e-commerce","theme":"Indicateurs e-commerce","goal":"Aprender a comunicarte sobre indicateurs e-commerce.","words":[["Les ventes ont augmenté ce mois-ci.","Las ventas aumentaron este mes."],["Notre panier moyen est plus élevé.","Nuestro ticket promedio es mayor."],["Nous devons réduire les coûts.","Debemos reducir los costos."],["Quel est notre retour sur les dépenses publicitaires ?","¿Cuál es nuestro retorno sobre inversión publicitaria?"],["Regardons le tableau de bord.","Revisemos el tablero de indicadores."]],"grammar":"«Chiffre d'affaires» es facturación, no necesariamente ganancia.","tip":"«Chiffre» contiene el sonido /ʃ/ de ch.","mission":["Escribe en francés: «¿Cuál es nuestro retorno sobre inversión publicitaria?»","Quel est notre retour sur les dépenses publicitaires ?"]},{"title":"Négocier","theme":"Négocier","goal":"Aprender a comunicarte sobre négocier.","words":[["Quel est votre budget ?","¿Cuál es su presupuesto?"],["Pouvons-nous discuter du prix ?","¿Podemos hablar del precio?"],["Nous pouvons proposer une réduction.","Podemos ofrecer un descuento."],["Mettons-nous d'accord sur le délai.","Pongámonos de acuerdo sobre el plazo."],["Cela me convient.","Eso me parece bien."]],"grammar":"«Pourrions-nous… ?» permite proponer algo cortésmente.","tip":"«Budget» se pronuncia /bydʒɛ/, con u francesa y final no muda.","mission":["Escribe en francés: «Pongámonos de acuerdo sobre el plazo.»","Mettons-nous d'accord sur le délai."]},{"title":"Mon parcours professionnel","theme":"Mon parcours professionnel","goal":"Aprender a comunicarte sobre mon parcours professionnel.","words":[["Je dirige une agence de marketing.","Dirijo una agencia de marketing."],["Nous aidons les marques à grandir.","Ayudamos a las marcas a crecer."],["Mon objectif principal est la croissance.","Mi objetivo principal es el crecimiento."],["J'ai de l'expérience en publicité.","Tengo experiencia en publicidad."],["J'aimerais travailler avec vous.","Me gustaría trabajar con usted."]],"grammar":"«Je dirige…» sirve para explicar que estás al frente de una empresa.","tip":"«Agence» se pronuncia aproximadamente «a-zhans» con vocal nasal final.","mission":["Escribe en francés: «Tengo experiencia en publicidad.»","J'ai de l'expérience en publicité."]},{"title":"Défi final","theme":"Défi final","goal":"Aprender a comunicarte sobre défi final.","words":[["Bonjour, ravi de vous rencontrer.","Hola, encantado de conocerle."],["Permettez-moi de présenter notre entreprise.","Permítame presentar nuestra empresa."],["Nous aidons les entreprises à obtenir des résultats.","Ayudamos a las empresas a obtener resultados."],["Quel défi rencontrez-vous ?","¿Qué desafío está enfrentando?"],["Fixons une réunion la semaine prochaine.","Agendemos una reunión la próxima semana."]],"grammar":"Combina una presentación breve, propuesta de valor, pregunta y siguiente paso.","tip":"Pronuncia en grupos cortos; la liaison correcta ayuda a sonar natural.","mission":["Escribe en francés: «¿Qué desafío está enfrentando?»","Quel défi rencontrez-vous ?"]}]};
